        if (!levelManager.hasRequiredEntityLevel(entityAccessor.getEntity().getType())) {
            for (Map.Entry<Integer, Integer> entry : levelManager.getRequiredEntityLevel(entityAccessor.getEntity().getType()).entrySet()) {
